import json,sys,time,math
sys.path.insert(0,'/tmp'); from optimize_schedules import Problem
wp,sp,out=sys.argv[1:4]; limit=float(sys.argv[4]) if len(sys.argv)>4 else 300
p=Problem(wp); data=json.load(open(sp))['presses']; ji={x:i for i,x in enumerate(p.jid)}
s=[[ji[j] for j in data.get(pid,[])] for pid in p.pid]; costs=p.costs(s); total=sum(costs); start=time.monotonic(); rnd=0
print('start',total,flush=True)
while time.monotonic()-start<limit:
 rnd+=1; bestdelta=0; best=None; checked=0
 # all relocations
 for a in range(p.P):
  for i,j in enumerate(s[a]):
   for b in p.eligible[j]:
    for k in range(len(s[b])+1):
     if a==b and (k==i or k==i+1): continue
     if a==b:
      ns=s[a][:]; x=ns.pop(i); kk=k-(k>i); ns.insert(kk,x); nc=p.pcost(a,ns); d=nc-costs[a]
      cand=('m1',a,i,b,kk,nc)
     else:
      sa=s[a][:i]+s[a][i+1:]; sb=s[b][:k]+[j]+s[b][k:]; na=p.pcost(a,sa); nb=p.pcost(b,sb); d=na+nb-costs[a]-costs[b]
      cand=('m2',a,i,b,k,na,nb)
     checked+=1
     if d<bestdelta: bestdelta=d;best=cand
 # all swaps
 for a in range(p.P):
  for i,j in enumerate(s[a]):
   for b in range(a,p.P):
    k0=i+1 if a==b else 0
    for k in range(k0,len(s[b])):
     h=s[b][k]
     if p.jton[j]>p.ton[b] or p.jton[h]>p.ton[a]: continue
     if a==b:
      ns=s[a][:];ns[i],ns[k]=ns[k],ns[i];nc=p.pcost(a,ns);d=nc-costs[a];cand=('s1',a,i,k,nc)
     else:
      sa=s[a][:];sb=s[b][:];sa[i],sb[k]=h,j;na=p.pcost(a,sa);nb=p.pcost(b,sb);d=na+nb-costs[a]-costs[b];cand=('s2',a,i,b,k,na,nb)
     checked+=1
     if d<bestdelta:bestdelta=d;best=cand
 if best is None:
  print('local optimum round',rnd,'checked',checked,'cost',total,flush=True);break
 t=best[0]
 if t=='m1': _,a,i,b,k,nc=best;j=s[a].pop(i);s[b].insert(k,j);costs[a]=nc
 elif t=='m2': _,a,i,b,k,na,nb=best;j=s[a].pop(i);s[b].insert(k,j);costs[a]=na;costs[b]=nb
 elif t=='s1': _,a,i,k,nc=best;s[a][i],s[a][k]=s[a][k],s[a][i];costs[a]=nc
 else: _,a,i,b,k,na,nb=best;s[a][i],s[b][k]=s[b][k],s[a][i];costs[a]=na;costs[b]=nb
 total+=bestdelta;print('round',rnd,'delta',bestdelta,'cost',total,best[:5],flush=True)
p.output(s,out);print('FINAL',sum(p.costs(s)),flush=True)
